/**
 * The whole bracket: it replaces every match the event has. Each team appears at most once, there is exactly one final in the last round named, and two matches never advance to the same side.
 */
export type LoadSportEventBracketRequest = {
    matches: Array<{
        /**
         * A round the event has.
         */
        roundNumber: number;
        /**
         * Unique within its round (#2161): the match's place in the round and its display order.
         */
        matchNumber: number;
        /**
         * Side 1 and side 2, once each. A synced game has its away team on side 1 and its home team on side 2.
         */
        sides: Array<{
            /**
             * The side: 1 or 2.
             */
            sideNumber: number;
            /**
             * A field row of the event, or null when an earlier match's winner fills the side (or its team is not known yet).
             */
            sportEventParticipantId: string | null;
            /**
             * Where the side plays game 1: NONE for both sides at a neutral site, else one HOME and one AWAY.
             */
            homeAway: 'HOME' | 'AWAY' | 'NONE';
        }>;
        isNeutralSite: boolean;
        scheduledDate: string | null;
        /**
         * Where the winner moves on to; null for the final. In a league that reseeds, also null for each match of a round whose winners are placed by seed.
         */
        advancesTo: {
            /**
             * A later round of this bracket.
             */
            roundNumber: number;
            /**
             * A match of that round.
             */
            matchNumber: number;
            /**
             * The side of that match the winner fills, which must not name a team.
             */
            sideNumber: number;
        } | null;
        /**
         * The region or conference the match is played in; omitted or null for none.
         */
        regionLabel?: string | null;
    }>;
};

/**
 * One match edit. Its time and site can change at any point; its sides only until the event is released; its spread until someone picks the game.
 */
export type UpdateSportEventRoundMatchRequest = {
    /**
     * Both sides' teams; omitted keeps them, and a null team empties its side. Only until the event is released.
     */
    sides?: Array<{
        /**
         * The side: 1 or 2.
         */
        sideNumber: number;
        /**
         * A field row of the event, or null when an earlier match's winner fills the side (or its team is not known yet).
         */
        sportEventParticipantId: string | null;
    }>;
    isNeutralSite?: boolean;
    /**
     * Omitted keeps it; null clears it.
     */
    scheduledDate?: string | null;
    /**
     * The points spread on side 1, in half points (-3.5: side 1 favoured by 3.5). Omitted keeps it; null clears it. Once the event is released, only while nobody has picked the game.
     */
    spread?: number | null;
};

/**
 * A match's result: who won, or a tie, and both scores or neither. A match that ended early says how (ending). The winner's score must be the higher, except in a bracket match of a sport settled by shoot-out, where a level score takes both shoot-out scores and the winner's shoot-out score is the higher. Shoot-out scores are refused anywhere else. A tie, only in a game of a week, has level scores.
 */
export type RecordSportEventRoundMatchResultRequest = {
    /**
     * The side that won; null for a tie (#792), which needs both scores, level. Only a game of a week, which forms no bracket, can end in a tie.
     */
    winnerSideNumber: number | null;
    /**
     * Side 1 and side 2, once each: both scores or neither.
     */
    sides: Array<{
        /**
         * The side: 1 or 2.
         */
        sideNumber: number;
        /**
         * The side's score (games won, for a series), or null with the other side's null too.
         */
        score: number | null;
        /**
         * The side's kicks scored in a shoot-out, for a bracket match level after extra time in a sport settled that way; omitted or null with the other side's for none.
         */
        shootoutScore?: number | null;
    }>;
    /**
     * How the match ended; omitted is PLAYED. A RETIREMENT or DEFAULT takes both scores or neither, and the winner's may be the lower (where it stopped); a WALKOVER takes no scores. Neither a tie nor a shoot-out ends early.
     */
    ending?: 'PLAYED' | 'RETIREMENT' | 'WALKOVER' | 'DEFAULT';
};

/**
 * Both sides' score at the end of one period, as the scoreboard shows it. Neither may be below its score at an earlier period's end, or above its score at a later one's or its final score.
 */
export type RecordSportEventMatchPeriodScoreRequest = {
    /**
     * Side 1 and side 2, once each.
     */
    sides: Array<{
        /**
         * The side: 1 or 2.
         */
        sideNumber: number;
        /**
         * The side's score at the end of the period, earlier periods included.
         */
        score: number;
    }>;
};

/**
 * Both sides of one match of a reseeded round.
 */
export type RoundMatchupDto = {
    /**
     * A match of the round, numbered within it.
     */
    matchNumber: number;
    /**
     * Side 1 and side 2, once each.
     */
    sides: Array<{
        /**
         * The side: 1 or 2. The better seed hosts, on side 2.
         */
        sideNumber: number;
        /**
         * The field row on the side.
         */
        sportEventParticipantId: string;
    }>;
};

/**
 * The pairing the server proposes for a reseeded round: in each region the best seed left hosts the worst, the second best the second worst, and a team already holding its place keeps it.
 */
export type SportEventRoundMatchupsResponse = {
    /**
     * One per match of the round, in match-number order.
     */
    matches: Array<{
        /**
         * A match of the round, numbered within it.
         */
        matchNumber: number;
        /**
         * Side 1 and side 2, once each.
         */
        sides: Array<{
            /**
             * The side: 1 or 2. The better seed hosts, on side 2.
             */
            sideNumber: number;
            /**
             * The field row on the side.
             */
            sportEventParticipantId: string;
        }>;
    }>;
};

/**
 * A reseeded round's teams, all at once. Every team left in the round plays once, in its own region, and a team holding its place (a bye, a linked winner) keeps it.
 */
export type SetSportEventRoundMatchupsRequest = {
    /**
     * Every match of the round, once each.
     */
    matches: Array<{
        /**
         * A match of the round, numbered within it.
         */
        matchNumber: number;
        /**
         * Side 1 and side 2, once each.
         */
        sides: Array<{
            /**
             * The side: 1 or 2. The better seed hosts, on side 2.
             */
            sideNumber: number;
            /**
             * The field row on the side.
             */
            sportEventParticipantId: string;
        }>;
    }>;
};

/**
 * A provider's identifier for a participant — how synced data finds them.
 */
export type ParticipantProviderMappingDto = {
    id: string;
    participantId: string;
    /**
     * The participant's sport league: a feed id names one participant per sport league.
     */
    sportLeagueId: string;
    /**
     * The participant's kind: a team id and a player id the feed numbers alike never collide.
     */
    participantType: 'INDIVIDUAL' | 'TEAM';
    /**
     * The Provider that knows the participant by externalId.
     */
    providerId: string;
    /**
     * That provider's name.
     */
    providerName: string;
    /**
     * The provider's own id for the participant, never prefixed.
     */
    externalId: string;
    /**
     * ISO 8601 datetime string.
     */
    mappedAt: string;
};

