/**
 * An event's tiers.
 */
export type SportEventTierListResponse = {
    /**
     * By tier number.
     */
    tiers: Array<{
        id: string;
        /**
         * The Season slot of the event whose tier set the tier is in (#2044).
         */
        seasonSlotId: string;
        /**
         * Stable key; assignments name a tier by it.
         */
        tierKey: string;
        /**
         * Order among the event's tiers; 1 first. A tier stores no name: screens call it "Tier N" by this number.
         */
        tierNumber: number;
    }>;
};

/**
 * The event's full tier list, replacing the current one.
 */
export type ReplaceSportEventTiersRequest = {
    tiers: Array<{
        tierKey: string;
        tierNumber: number;
    }>;
    /**
     * A tierKey from this request; where participants in a removed tier go once a tier was placed by hand, and required then when a removed tier still has participants. Ignored otherwise: the field is placed in the new tiers afresh.
     */
    reassignOrphansTo?: string;
};

/**
 * Fills the event's tiers from the active field, in the order auto-assigned prices use too (#1807): odds, then seed, then rank, decided for the whole field by the first value every participant has, then name.
 */
export type AutoAssignSportEventTiersRequest = {
    /**
     * Participants per tier but the last, instead of the sport league's tier profile's; the last tier takes the rest, or up to the profile's cap. Omitted: an event with its profile's tier count gets the profile's tier size (10 for golf's six tiers of ten) while the field reaches the last tier; any other tier count, or a smaller field, gets the active field spread evenly over its tiers, larger tiers first (22 on four tiers is 6/6/5/5). 422 TIER_SIZE_NOT_FOR_RANGES when the league's tier profile is RANGES: its ranges place the field, so a tier size has nothing to set.
     */
    tierSize?: number;
};

/**
 * The drag-and-drop tier save.
 */
export type ReplaceSportEventTierAssignmentsRequest = {
    /**
     * The full desired placement, applied all or none.
     */
    assignments: Array<{
        sportEventParticipantId: string;
        tierKey: string;
        tierOrderIndex: number;
    }>;
};

/**
 * The values an event slot's set was priced with for budget contests, and the profile they started from.
 */
export type SlotPricing = {
    /**
     * Whole dollars. The salary cap the prices are a share of, and the cap of every budget contest on the event.
     */
    salaryCap: number;
    /**
     * Whole dollars. Every price is rounded to a multiple of it. At most the worst golfer's price.
     */
    unit: number;
    /**
     * The best seed's price, as a percentage of the salary cap.
     */
    topSharePercent: number;
    /**
     * The worst seed's price, as a percentage of the salary cap. At most `topSharePercent`.
     */
    floorSharePercent: number;
    /**
     * How fast prices fall from the top: 1 is a straight line; higher keeps the top few expensive and drops the middle of the field towards the floor.
     */
    steepness: number;
    /**
     * The pricing profile the values started from. The admin may have changed any value before assigning.
     */
    platformPricingProfileId: string;
};

/**
 * The tier layout an event slot's set was last auto-tiered with: its tier profile's, with any tier size an admin sent instead.
 */
export type SlotTierLayout = {
    type: 'EQUAL_GROUPS';
    /**
     * How many tiers a new event starts with.
     */
    tierCount: number;
    /**
     * How many participants auto-tiering puts in each tier before the last.
     */
    tierSize: number;
    /**
     * What the last tier takes: ALL_REMAINING, everyone left; or CAPPED, at most lastTierMax, with anyone beyond in no tier and not pickable.
     */
    lastTier: 'ALL_REMAINING' | 'CAPPED';
    /**
     * The most the last tier takes when lastTier is CAPPED. Null when it is ALL_REMAINING.
     */
    lastTierMax: number | null;
    /**
     * The tier profile the layout came from: the sport league's when the set was tiered.
     */
    platformTierProfileId: string;
} | {
    type: 'RANGES';
    /**
     * Each tier's seeds or ranks, by tier number from 1: one per tier, with no gap or overlap, and only the last open-ended.
     */
    ranges: Array<{
        /**
         * The tier, from 1.
         */
        tierNumber: number;
        /**
         * The lowest seed or rank the tier takes.
         */
        fromValue: number;
        /**
         * The highest seed or rank the tier takes. Null: everyone from fromValue on, which only the last tier may be.
         */
        toValue: number | null;
    }>;
    /**
     * The tier profile the layout came from: the sport league's when the set was tiered.
     */
    platformTierProfileId: string;
};

/**
 * Prices the active field on the budget curve with these values, best seed first and golfers with no seed last, and records them on the slot as its pricing (#2044). The values usually come from a Budget pricing profile, possibly changed; platformPricingProfileId names that profile (404 PLATFORM_PRICING_PROFILE_NOT_FOUND for none).
 */
export type AutoAssignSportEventPricesRequest = {
    /**
     * Whole dollars. The salary cap the prices are a share of, and the cap of every budget contest on the event.
     */
    salaryCap: number;
    /**
     * Whole dollars. Every price is rounded to a multiple of it. At most the worst golfer's price.
     */
    unit: number;
    /**
     * The best seed's price, as a percentage of the salary cap.
     */
    topSharePercent: number;
    /**
     * The worst seed's price, as a percentage of the salary cap. At most `topSharePercent`.
     */
    floorSharePercent: number;
    /**
     * How fast prices fall from the top: 1 is a straight line; higher keeps the top few expensive and drops the middle of the field towards the floor.
     */
    steepness: number;
    /**
     * The pricing profile the values started from. The admin may have changed any value before assigning.
     */
    platformPricingProfileId: string;
};

/**
 * Pricing values to preview on a slot's active field before assigning them (#2107): the same five values autoAssignEventSlotPrices takes, without the profile they started from.
 */
export type SportEventPricePreviewQuery = {
    /**
     * Whole dollars. The salary cap the prices are a share of, and the cap of every budget contest on the event.
     */
    salaryCap: number;
    /**
     * Whole dollars. Every price is rounded to a multiple of it. At most the worst golfer's price.
     */
    unit: number;
    /**
     * The best seed's price, as a percentage of the salary cap.
     */
    topSharePercent: number;
    /**
     * The worst seed's price, as a percentage of the salary cap. At most `topSharePercent`.
     */
    floorSharePercent: number;
    /**
     * How fast prices fall from the top: 1 is a straight line; higher keeps the top few expensive and drops the middle of the field towards the floor.
     */
    steepness: number;
};

/**
 * What pricing a slot's active field with the values sent would charge its best and worst participant (#2107). Nothing is written.
 */
export type SportEventPricePreviewResponse = {
    /**
     * The participants the slot's prices would go to: its active field, less anyone knocked out in an earlier slot.
     */
    activeParticipantCount: number;
    /**
     * Whole dollars: the first participant's price on the curve; null with no active participant.
     */
    bestPrice: number | null;
    /**
     * Whole dollars: the last participant's price on the curve; null with no active participant.
     */
    worstPrice: number | null;
};

/**
 * A field row's tier placement and price, each set independently.
 */
export type SportEventParticipantValuationDto = {
    id: string;
    /**
     * The tier the participant is placed in; null when untiered.
     */
    sportEventTierId: string | null;
    /**
     * Order within the tier.
     */
    tierOrderIndex: number | null;
    tierAssignedSource: 'AUTO_ODDS' | 'AUTO_SEED' | 'AUTO_RANKING' | 'MANUAL' | null;
    /**
     * Price in a budget contest; null when unpriced.
     */
    price: number | null;
    priceAssignedSource: 'AUTO_ODDS' | 'AUTO_SEED' | 'AUTO_RANKING' | 'MANUAL' | null;
};

/**
 * A field row's running standing. The score lives in the sport's extension.
 */
export type SportEventParticipantStandingDto = {
    id: string;
    /**
     * The participant's place within this event as it stands — its leaderboard position, direction-free: 1 is best in every sport. Not their rank coming in: that is the field row's `ranking`.
     */
    position: number | null;
    /**
     * Position as shown, e.g. "T3".
     */
    displayPosition: string | null;
    /**
     * ELIMINATED covers a missed cut; golf surfaces show it as "Cut".
     */
    status: 'ACTIVE' | 'IN_PROGRESS' | 'COMPLETE' | 'WITHDRAWN' | 'ELIMINATED';
    /**
     * ISO 8601 datetime string.
     */
    asOf: string | null;
    /**
     * The highest round the participant has a score in, read off its rounds; null before it has one, and for a participant scored by match or by finish.
     */
    currentRound: number | null;
    /**
     * Present for a golf event with scores; null otherwise.
     */
    golf: {
        eventScoreToPar: number;
        eventStrokes: number;
    } | null;
};

/**
 * A field row's part in one round.
 */
export type SportEventParticipantRoundDto = {
    id: string;
    sportEventRoundId: string;
    roundNumber: number;
    /**
     * How the participant's part in the round ended, as the round's Game records it; null while they are still playing it. A missed cut is not a round status: it is the standing's ELIMINATED.
     */
    status: 'FINISHED' | 'DID_NOT_FINISH' | 'DISQUALIFIED' | 'DID_NOT_START' | null;
    /**
     * How many of the round's periods the participant has completed (holes, in golf), as the feed reports it; null when it reports none.
     */
    periodsCompleted: number | null;
    /**
     * ISO 8601 datetime string.
     */
    completedAt: string | null;
    /**
     * Present once a golf round is scored.
     */
    golf: {
        strokes: number;
        scoreToPar: number;
    } | null;
};

/**
 * A participant on an event's field, with everything the event records about them.
 */
export type SportEventParticipantDto = {
    /**
     * Field row identifier.
     */
    id: string;
    sportEventId: string;
    participantId: string;
    /**
     * The field row's place in its event (#2184): ACTIVE while it competes; WITHDRAWN, ELIMINATED (a missed cut or a knock-out) or DISQUALIFIED once it is out.
     */
    status: 'ACTIVE' | 'WITHDRAWN' | 'ELIMINATED' | 'DISQUALIFIED';
    /**
     * The participant's rank coming into this event — seeded from the provider's ranking (a world ranking, say), then editable. Not their place in the event: that is `standing.position`.
     */
    ranking: number | null;
    oddsToWin: number | null;
    seedNumber: number | null;
    /**
     * The canonical participant.
     */
    participant: {
        /**
         * Participant identifier.
         */
        id: string;
        /**
         * The one sport league the participant competes in; the sport is the league's.
         */
        sportLeagueId: string;
        /**
         * Current rank in the sport league; 1 is best. Null when unranked.
         */
        ranking: number | null;
        /**
         * Primary participant display name.
         */
        name: string;
        /**
         * Whether the participant is an individual or team.
         */
        participantType: 'INDIVIDUAL' | 'TEAM';
        /**
         * Deprecated (#2040): never sent. A participant's feed ids are its provider mappings.
         */
        externalId?: string;
        /**
         * First name when the participant is a person.
         */
        firstName?: string;
        /**
         * Last name when the participant is a person.
         */
        lastName?: string;
        /**
         * Short-form display name for compact UI surfaces.
         */
        shortName?: string;
        /**
         * Participant nationality or country code when known.
         */
        nationality?: string;
        /**
         * A team's abbreviation as its feed sends it (KC); null for a player and for a team its feed gives none. A player's team and position are their roster row's.
         */
        abbreviation?: string | null;
        /**
         * Current participant lifecycle or availability status.
         */
        status: 'ACTIVE' | 'INACTIVE' | 'RETIRED' | 'SUSPENDED';
        /**
         * Normalized participant injury or availability state.
         */
        injuryStatus: {
            /**
             * Current injury or availability status code.
             */
            status: 'HEALTHY' | 'QUESTIONABLE' | 'DOUBTFUL' | 'OUT' | 'WITHDRAWN' | 'SUSPENDED' | 'SCRATCHED';
            /**
             * Optional injury-status detail or summary.
             */
            detail?: string;
            /**
             * Expected return timestamp when known.
             */
            expectedReturn?: string;
            /**
             * When the injury-status record was last updated.
             */
            updatedAt?: string;
            /**
             * Source that provided the injury-status update.
             */
            source?: string;
        };
        /**
         * Optional participant image URL.
         */
        photoUrl?: string | null;
        /**
         * When the participant image metadata was last refreshed.
         */
        photoLastUpdated?: string;
        /**
         * Deprecated (#2040): always empty. A participant's feed ids are its provider mappings.
         */
        externalIds: {
            [key: string]: string;
        };
        /**
         * When the participant record was created.
         */
        createdAt: string;
        /**
         * When the participant record was last updated.
         */
        updatedAt: string;
    };
    /**
     * Null until a tier or price is set.
     */
    valuation: {
        id: string;
        /**
         * The tier the participant is placed in; null when untiered.
         */
        sportEventTierId: string | null;
        /**
         * Order within the tier.
         */
        tierOrderIndex: number | null;
        tierAssignedSource: 'AUTO_ODDS' | 'AUTO_SEED' | 'AUTO_RANKING' | 'MANUAL' | null;
        /**
         * Price in a budget contest; null when unpriced.
         */
        price: number | null;
        priceAssignedSource: 'AUTO_ODDS' | 'AUTO_SEED' | 'AUTO_RANKING' | 'MANUAL' | null;
    } | null;
    /**
     * Null until the participant has a scored round, or a race result.
     */
    standing: {
        id: string;
        /**
         * The participant's place within this event as it stands — its leaderboard position, direction-free: 1 is best in every sport. Not their rank coming in: that is the field row's `ranking`.
         */
        position: number | null;
        /**
         * Position as shown, e.g. "T3".
         */
        displayPosition: string | null;
        /**
         * ELIMINATED covers a missed cut; golf surfaces show it as "Cut".
         */
        status: 'ACTIVE' | 'IN_PROGRESS' | 'COMPLETE' | 'WITHDRAWN' | 'ELIMINATED';
        /**
         * ISO 8601 datetime string.
         */
        asOf: string | null;
        /**
         * The highest round the participant has a score in, read off its rounds; null before it has one, and for a participant scored by match or by finish.
         */
        currentRound: number | null;
        /**
         * Present for a golf event with scores; null otherwise.
         */
        golf: {
            eventScoreToPar: number;
            eventStrokes: number;
        } | null;
    } | null;
    /**
     * By round number.
     */
    rounds: Array<{
        id: string;
        sportEventRoundId: string;
        roundNumber: number;
        /**
         * How the participant's part in the round ended, as the round's Game records it; null while they are still playing it. A missed cut is not a round status: it is the standing's ELIMINATED.
         */
        status: 'FINISHED' | 'DID_NOT_FINISH' | 'DISQUALIFIED' | 'DID_NOT_START' | null;
        /**
         * How many of the round's periods the participant has completed (holes, in golf), as the feed reports it; null when it reports none.
         */
        periodsCompleted: number | null;
        /**
         * ISO 8601 datetime string.
         */
        completedAt: string | null;
        /**
         * Present once a golf round is scored.
         */
        golf: {
            strokes: number;
            scoreToPar: number;
        } | null;
    }>;
    /**
     * Present once a race result is entered for a finish-position event (a horse race); null otherwise.
     */
    race: {
        /**
         * Finishing place, 1 for the winner; runners in a dead heat share a place. Set only when resultStatus is FINISHED; null until entered.
         */
        finishPosition: number | null;
        /**
         * Post position (or grid slot, or starting spot); null when not entered.
         */
        startPosition: number | null;
        /**
         * How the race ended for this runner. Every status but FINISHED scores the contest's "did not finish" points.
         */
        resultStatus: 'FINISHED' | 'DID_NOT_FINISH' | 'DISQUALIFIED' | 'DID_NOT_START';
        /**
         * Whether the race's result is official. Contest scoring counts a result only once it is.
         */
        isOfficial: boolean;
    } | null;
    /**
     * Whether the participant is affiliated with the event's sport league; false flags an invite from elsewhere. (Admin-only: operational detail no member surface reads.)
     */
    affiliatedWithSportLeague: boolean;
    /**
     * ISO 8601 datetime string.
     */
    createdAt: string;
    /**
     * ISO 8601 datetime string.
     */
    updatedAt: string;
};

