/**
 * One background job on the Activity grid.
 */
export type ActivityJobDto = {
    id: string;
    /**
     * The job's handler. Its kind follows from it.
     */
    type: 'SYNC_EVENT_FIELD' | 'SYNC_EVENT_SCORES' | 'CONTEST_STARTED_EMAILS' | 'CONTEST_SETTLED_EMAILS' | 'CONTEST_EVENT_CHANGED_EMAILS' | 'CONTEST_REOPENED_EMAILS' | 'SETTLE_SPORT_EVENT_CONTESTS' | 'SETTLE_GAME_CONTESTS' | 'REBUILD_LEADERBOARDS' | 'SYNC_LEAGUE_EVENTS' | 'RELEASE_SPORT_EVENT' | 'SYNC_EVENT_GAMES_AND_TIERS' | 'ACTIVATE_EVENT_CONTESTS' | 'FOLLOW_POSTPONED_EVENT_CONTESTS' | 'RESOLVE_MAPPED_PARTICIPANT_FINDINGS' | 'REFRESH_SLOT_TIEBREAKERS' | 'SYNC_LEAGUE_ROSTER' | 'REFRESH_SLOT_STATUS' | 'REFRESH_EVENT_STATUS' | 'CLOSE_LEAGUE_CHAMPIONSHIP_YEAR' | 'CLOSE_SEASON_CHAMPIONSHIP_YEARS';
    /**
     * What a job is about: a provider SYNC, EMAIL to a league, contest SETTLEMENT, an event's RELEASE, or OTHER.
     */
    kind: 'SYNC' | 'EMAIL' | 'SETTLEMENT' | 'RELEASE' | 'OTHER';
    /**
     * QUEUED waits for its run time, RUNNING is claimed, SUCCEEDED finished, FAILED will not run again.
     */
    status: 'QUEUED' | 'RUNNING' | 'SUCCEEDED' | 'FAILED';
    /**
     * The sport league a whole-league job is about, such as its events sync; null for a job on one event.
     */
    sportLeagueId: string | null;
    /**
     * The event the job is about; null when it is about none.
     */
    sportEventId: string | null;
    /**
     * The sport league the job is about, for display: its own league, or for a job on an event, the event's league. Null when it is about neither.
     */
    sportLeague: {
        id: string;
        name: string;
    } | null;
    /**
     * The event the job is about, for display; null when it is about none.
     */
    sportEvent: {
        id: string;
        name: string;
    } | null;
    /**
     * Tries so far, counting one in progress.
     */
    attempts: number;
    /**
     * When it is or was due: first queued, or retried after a failed try.
     */
    runAt: string;
    /**
     * When it was queued.
     */
    createdAt: string;
    /**
     * When it SUCCEEDED or FAILED.
     */
    completedAt: string | null;
    /**
     * The error of its last failed try.
     */
    lastError: string | null;
    /**
     * What started a job or sync run: a SCHEDULE, the provider's WEBHOOK, a person acting through a root ADMIN route (Sync now, Release) or a league's COMMISSIONER tools, or the SYSTEM (another job, or upkeep such as a stale board's rebuild). A person's trigger is the role the route requires, not their highest role. A sync run has its job's.
     */
    trigger: 'SCHEDULE' | 'WEBHOOK' | 'ADMIN' | 'COMMISSIONER' | 'SYSTEM';
    /**
     * The person whose request started an ADMIN or COMMISSIONER job; null for any other trigger, or when that account was deleted.
     */
    startedBy: {
        id: string;
        /**
         * Their name, for display.
         */
        displayName: string;
    } | null;
    /**
     * When its latest try started; null until it is first claimed.
     */
    startedAt: string | null;
    /**
     * How long its latest try took, in whole seconds, from startedAt to completedAt; null until it SUCCEEDED or FAILED.
     */
    durationSeconds: number | null;
    /**
     * How many rows a SUCCEEDED job created or changed: events, field participants, contests settled, boards rebuilt, emails queued. Null until it succeeds.
     */
    changedCount: number | null;
    /**
     * Why it did not do its work: set with lastError on a failed try (kept while it waits to be retried, and once FAILED), and on a SUCCEEDED job that was held back, such as a release whose checks failed (CHECK_FAILED). Null otherwise.
     */
    errorType: 'RATE_LIMITED' | 'TIMEOUT' | 'PROVIDER_ERROR' | 'BAD_DATA' | 'CHECK_FAILED' | 'OTHER' | null;
    /**
     * What its handler reported it did, once SUCCEEDED; null when it reported nothing. An events sync reports its created, updated and skipped counts and its run.
     */
    result: {
        [key: string]: unknown;
    } | null;
    /**
     * The provider sync runs the job ran, oldest first; read each with getProviderSyncRun. Empty for a job that is not a sync, or before a sync starts.
     */
    syncRunIds: Array<string>;
};

/**
 * Filters over Activity. A queue-time window bounds it; nothing pages it.
 */
export type ActivityListQuery = {
    /**
     * What a job is about: a provider SYNC, EMAIL to a league, contest SETTLEMENT, an event's RELEASE, or OTHER.
     */
    kind?: 'SYNC' | 'EMAIL' | 'SETTLEMENT' | 'RELEASE' | 'OTHER';
    /**
     * QUEUED waits for its run time, RUNNING is claimed, SUCCEEDED finished, FAILED will not run again.
     */
    status?: 'QUEUED' | 'RUNNING' | 'SUCCEEDED' | 'FAILED';
    /**
     * The league's own jobs and the jobs on any of its events.
     */
    sportLeagueId?: string;
    sportEventId?: string;
    /**
     * Earliest queue time to include. Defaults to 24 hours before `to`, or with a sportLeagueId or sportEventId, to 30 days before it: every job kept.
     */
    from?: string;
    /**
     * Latest queue time to include. Defaults to now.
     */
    to?: string;
};

/**
 * The jobs queued inside the window that match the filters, newest first.
 */
export type ActivityListResponse = {
    jobs: Array<{
        id: string;
        /**
         * The job's handler. Its kind follows from it.
         */
        type: 'SYNC_EVENT_FIELD' | 'SYNC_EVENT_SCORES' | 'CONTEST_STARTED_EMAILS' | 'CONTEST_SETTLED_EMAILS' | 'CONTEST_EVENT_CHANGED_EMAILS' | 'CONTEST_REOPENED_EMAILS' | 'SETTLE_SPORT_EVENT_CONTESTS' | 'SETTLE_GAME_CONTESTS' | 'REBUILD_LEADERBOARDS' | 'SYNC_LEAGUE_EVENTS' | 'RELEASE_SPORT_EVENT' | 'SYNC_EVENT_GAMES_AND_TIERS' | 'ACTIVATE_EVENT_CONTESTS' | 'FOLLOW_POSTPONED_EVENT_CONTESTS' | 'RESOLVE_MAPPED_PARTICIPANT_FINDINGS' | 'REFRESH_SLOT_TIEBREAKERS' | 'SYNC_LEAGUE_ROSTER' | 'REFRESH_SLOT_STATUS' | 'REFRESH_EVENT_STATUS' | 'CLOSE_LEAGUE_CHAMPIONSHIP_YEAR' | 'CLOSE_SEASON_CHAMPIONSHIP_YEARS';
        /**
         * What a job is about: a provider SYNC, EMAIL to a league, contest SETTLEMENT, an event's RELEASE, or OTHER.
         */
        kind: 'SYNC' | 'EMAIL' | 'SETTLEMENT' | 'RELEASE' | 'OTHER';
        /**
         * QUEUED waits for its run time, RUNNING is claimed, SUCCEEDED finished, FAILED will not run again.
         */
        status: 'QUEUED' | 'RUNNING' | 'SUCCEEDED' | 'FAILED';
        /**
         * The sport league a whole-league job is about, such as its events sync; null for a job on one event.
         */
        sportLeagueId: string | null;
        /**
         * The event the job is about; null when it is about none.
         */
        sportEventId: string | null;
        /**
         * The sport league the job is about, for display: its own league, or for a job on an event, the event's league. Null when it is about neither.
         */
        sportLeague: {
            id: string;
            name: string;
        } | null;
        /**
         * The event the job is about, for display; null when it is about none.
         */
        sportEvent: {
            id: string;
            name: string;
        } | null;
        /**
         * Tries so far, counting one in progress.
         */
        attempts: number;
        /**
         * When it is or was due: first queued, or retried after a failed try.
         */
        runAt: string;
        /**
         * When it was queued.
         */
        createdAt: string;
        /**
         * When it SUCCEEDED or FAILED.
         */
        completedAt: string | null;
        /**
         * The error of its last failed try.
         */
        lastError: string | null;
        /**
         * What started a job or sync run: a SCHEDULE, the provider's WEBHOOK, a person acting through a root ADMIN route (Sync now, Release) or a league's COMMISSIONER tools, or the SYSTEM (another job, or upkeep such as a stale board's rebuild). A person's trigger is the role the route requires, not their highest role. A sync run has its job's.
         */
        trigger: 'SCHEDULE' | 'WEBHOOK' | 'ADMIN' | 'COMMISSIONER' | 'SYSTEM';
        /**
         * The person whose request started an ADMIN or COMMISSIONER job; null for any other trigger, or when that account was deleted.
         */
        startedBy: {
            id: string;
            /**
             * Their name, for display.
             */
            displayName: string;
        } | null;
        /**
         * When its latest try started; null until it is first claimed.
         */
        startedAt: string | null;
        /**
         * How long its latest try took, in whole seconds, from startedAt to completedAt; null until it SUCCEEDED or FAILED.
         */
        durationSeconds: number | null;
        /**
         * How many rows a SUCCEEDED job created or changed: events, field participants, contests settled, boards rebuilt, emails queued. Null until it succeeds.
         */
        changedCount: number | null;
        /**
         * Why it did not do its work: set with lastError on a failed try (kept while it waits to be retried, and once FAILED), and on a SUCCEEDED job that was held back, such as a release whose checks failed (CHECK_FAILED). Null otherwise.
         */
        errorType: 'RATE_LIMITED' | 'TIMEOUT' | 'PROVIDER_ERROR' | 'BAD_DATA' | 'CHECK_FAILED' | 'OTHER' | null;
        /**
         * What its handler reported it did, once SUCCEEDED; null when it reported nothing. An events sync reports its created, updated and skipped counts and its run.
         */
        result: {
            [key: string]: unknown;
        } | null;
        /**
         * The provider sync runs the job ran, oldest first; read each with getProviderSyncRun. Empty for a job that is not a sync, or before a sync starts.
         */
        syncRunIds: Array<string>;
    }>;
};

